SZGame2D.onStart(function __szProjectRun() {
  const __szProjectRunContext = window.__SZProjectLifecycle.begin(() => SZGame2D.restart());
  // Ao iniciar
  SZGame2D.setupStage(640, 480, "#d9eec4");
  SZGame2D.enableClassicControls("always");
  const coelho = SZGame2D.createSprite({ x: 296, y: 392, w: 48, h: 48, image: "coelho" });
  const pinhas = SZGame2D.createGroup();
  const bolotas = SZGame2D.createGroup();
  let pontos = 0;
  SZGame2D.setHealth(coelho, 3);
  SZGame2D.setScene("inicio");
  // Quando acontecer
  SZGame2D.onKey("Enter", () => {
    if (SZGame2D.sceneIs("inicio")) {
      SZGame2D.setScene("jogando");
    } else if (SZGame2D.sceneIs("fim")) {
      SZGame2D.restart();
    } else if (SZGame2D.sceneIs("vitoria")) {
      SZGame2D.restart();
    }
  }, "bosque_chuva_de_pinhas_events_0");
  SZGame2D.onKey("Space", () => {
    if (SZGame2D.sceneIs("jogando")) {
      SZGame2D.spawnBullet(bolotas, { x: SZGame2D.centerX(coelho), y: SZGame2D.spriteY(coelho), radius: 6, color: "#a8743a", vx: 0, vy: -9 });
    }
  }, "bosque_chuva_de_pinhas_events_1");
  // Enquanto estiver rodando
  // O jogo roda 60 passos por segundo: cada volta desenha um "quadro" do filme.
  SZGame2D.gameLoop(function update() {
    SZGame2D.clear();
    SZGame2D.drawBackdrop(ctx, "bosque");
    if (SZGame2D.sceneIs("jogando")) {
      SZGame2D.arrowsX(coelho, 6);
      SZGame2D.clampToScreen(coelho, ctx);
      SZGame2D.drawSprite(ctx, coelho);
      SZGame2D.updateGroup(bolotas);
      SZGame2D.pruneOffscreen(ctx, bolotas, 40, (sprite) => {

      });
      SZGame2D.drawGroup(ctx, bolotas);
      SZGame2D.updateGroup(pinhas);
      SZGame2D.pruneOffscreen(ctx, pinhas, 40, (sprite) => {

      });
      SZGame2D.drawGroup(ctx, pinhas);
      SZGame2D.overlapGroups(bolotas, pinhas, (bolota, pinha) => {
        SZGame2D.removeFromGroup(bolotas, bolota);
        SZGame2D.removeFromGroup(pinhas, pinha);
        SZGame2D.explodeSprite(pinha, "#c58b4a");
        pontos = pontos + 1;
      });
      SZGame2D.drawScore(ctx, "Pontos:", pontos, 12, 30, "#1f4a3a", 24);
      SZGame2D.overlapSpriteGroup(() => coelho, pinhas, (pinha) => {
        SZGame2D.removeFromGroup(pinhas, pinha);
        SZGame2D.damageSprite(coelho, 1, 45);
        SZGame2D.shake(ctx, 6);
      });
      SZGame2D.drawSpriteHealth(ctx, coelho, "hearts", 12, 48, 22, "#e0565b");
      if (pontos >= 10) {
        SZGame2D.setScene("vitoria");
      }
      if (SZGame2D.healthDepleted(coelho)) {
        SZGame2D.setScene("fim");
      }
    } else if (SZGame2D.sceneIs("inicio")) {
      SZGame2D.showScreen(ctx, "A chuva de pinhas", "", "Aperte Enter para começar. Setas andam, espaço joga bolota", "#1f4a3a");
    } else if (SZGame2D.sceneIs("fim")) {
      SZGame2D.showScreen(ctx, "As vidas acabaram", "", "Aperte Enter para jogar de novo", "#1f4a3a");
    } else if (SZGame2D.sceneIs("vitoria")) {
      SZGame2D.showScreen(ctx, "Você quebrou dez pinhas", "", "Aperte Enter para jogar de novo", "#1f4a3a");
    }
  }, "bosque_chuva_de_pinhas_loops_0");
  SZGame2D.gameLoop(function __szPeriodicLoop() {
    if (SZGame2D.everyFrames("cada", 60)) {
      if (SZGame2D.sceneIs("jogando")) {

      }
    }
  });
}, "__sz-project");

